def bisect(f, lo, hi, tol=1e-10):
    assert f(lo) * f(hi) < 0, "needs a sign change"
    while hi - lo > tol:
        mid = (lo + hi) / 2
        if f(lo) * f(mid) <= 0:
            hi = mid
        else:
            lo = mid
    return (lo + hi) / 2

root = bisect(lambda x: x ** 3 + x - 1, 0, 1)
print(round(root, 8))          # 0.6823278
